import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  StyledSectionContainer,
  StyledSectionDescription,
} from '../../EmptyState.styles';
import type { EmptyStateSectionLevelProps } from '../../EmptyState.types';
import { getIllustration } from '../../utils';

export const SectionLevel = React.forwardRef<
  HTMLDivElement,
  EmptyStateSectionLevelProps
>(
  (
    {
      description,
      customIlustration,
      ilustrationName = 'beesAlert',
      className,
      ...props
    },
    forwardedRef,
  ) => {
    const illustration = getIllustration(customIlustration, ilustrationName);

    return (
      <StyledSectionContainer
        {...omitTransientProps(props)}
        ref={forwardedRef}
        className={className}
      >
        <img
          alt={illustration.alt}
          height={illustration.height}
          src={illustration.src}
          width={illustration.width}
        />
        {description ? (
          <StyledSectionDescription>{description}</StyledSectionDescription>
        ) : null}
      </StyledSectionContainer>
    );
  },
);

SectionLevel.displayName = 'EmptyState.SectionLevel';
